#include <ranges>
#include <sstream>
#include <cassert>
#include <type_traits>
#include <utility>
struct InputIterator {
    using value_type = int;
    using difference_type = std::ptrdiff_t;
    using iterator_concept = std::input_iterator_tag;
    int *position;
    int &operator*() const { return *position; }
    InputIterator &operator++() {
        ++position;
        return *this;
    }
    void operator++(int) { ++*this; }
};
int main() {
    int values[]{1, 2, 3, 4};
    auto chunks = std::views::chunk(values, 2);
    auto position = chunks.begin();
    (void)position.base();
    assert(std::ranges::distance(*position) == 2);
    auto countedInput = std::ranges::subrange(
        std::counted_iterator(InputIterator{values}, 4), std::default_sentinel);
    auto singlePass = countedInput | std::views::chunk(2);
    auto outer = singlePass.begin();
    auto part = *outer;
    auto inner = part.begin();
    assert(*inner == 1);
    std::ranges::iter_swap(inner, inner);
    assert(singlePass.end() - outer == 2);
    assert(part.end() - inner == 2);
    (void)inner.base();
    assert(std::ranges::iter_move(inner) == 1);
    ++inner;
    assert(*inner == 2);
    ++outer;
    assert(*(*outer).begin() == 3);
    // Iterator assignment is deleted for the single-pass inner/outer iterator.
    static_assert(!std::is_copy_assignable_v<decltype(inner)>);
}
